// só segue se o aviso chegou pela entrada 'pedido'
if ($input.first().json.rota !== 'pedido') return [];
const brl = (v) => 'R$ ' + Number(v).toFixed(2).replace('.', ',');
const b = $input.first().json.body || {};
const cfg = $('Config').first().json;
if (!cfg.token || b.token !== cfg.token) throw new Error('Token inválido');
const p = b.pedido;
if (!p || !p.id || !p.cliente_telefone) return [];
const lista = (p.itens || []).map((i) =>
  `• ${i.qtd}× ${i.nome}${i.detalhe ? ' (' + i.detalhe + ')' : ''}${i.obs ? ' · obs: ' + i.obs : ''} — ${brl(i.preco)}`).join('\n');
const pagto = {
  pix: 'Pix (aguardando comprovante)',
  cartao: p.tipo === 'entrega' ? 'Cartão na entrega' : 'Cartão',
  dinheiro: 'Dinheiro' + (p.troco_para ? ` (paga com ${brl(p.troco_para)}, troco de ${brl(p.troco_para - p.total)})` : ' (sem troco)'),
}[p.pagamento] || 'A combinar';
const recebe = p.tipo === 'entrega' ? `Entrega: ${p.endereco}` : 'Retirada no balcão';
const saida = [];

if (['site', 'whatsapp', 'manu'].includes(p.origem) && cfg.numero_loja) {
  saida.push({ numero: cfg.numero_loja, texto:
    `*NOVO PEDIDO ${p.origem === 'site' ? 'PELO SITE' : 'PELA MANU'} #${p.id}*\nCliente: ${p.cliente_nome} (${p.cliente_telefone})\n${recebe}\n\n${lista}\n\n` +
    (p.observacoes ? `Obs.: ${p.observacoes}\n\n` : '') +
    `*Total: ${brl(p.total)}*\nPagamento: ${pagto}\n\nConfirme no painel de pedidos.` });
}

let cli = `Olá, ${p.cliente_nome}! Recebemos seu pedido *#${p.id}* na Naturalle Mania.\n\n${lista}\n\n`;
if (Number(p.taxa_entrega)) cli += `Taxa de entrega: ${brl(p.taxa_entrega)}\n`;
if (Number(p.acrescimo_cartao)) cli += `Acréscimo da maquininha: ${brl(p.acrescimo_cartao)}\n`;
cli += `*Total: ${brl(p.total)}*\n${recebe}\n\n`;
if (p.pagamento === 'pix') {
  cli += `Para pagar via Pix, use a chave:\n*${cfg.pix_chave}*\n(${cfg.pix_nome})\n\nDepois é só responder aqui com a foto do comprovante.`;
} else if (p.pagamento === 'cartao') {
  cli += p.tipo === 'entrega' ? 'Pagamento no cartão na entrega: o entregador leva a maquininha.' : 'Pagamento no cartão na retirada.';
} else if (p.pagamento === 'dinheiro') {
  cli += 'Pagamento em dinheiro' + (p.troco_para ? `: você paga com ${brl(p.troco_para)} e recebe ${brl(p.troco_para - p.total)} de troco.` : ', valor certo (sem troco).');
}
cli += p.status === 'novo' ? '\n\nJá já confirmamos e avisamos por aqui!' : '\n\nJá está sendo preparado. Avisamos por aqui a cada etapa!';
saida.push({ numero: p.cliente_telefone, texto: cli });

return saida.map((json) => ({ json }));

// só segue se o aviso chegou pela entrada 'status'
if ($input.first().json.rota !== 'status') return [];
const brl = (v) => 'R$ ' + Number(v).toFixed(2).replace('.', ',');
const b = $input.first().json.body || {};
const cfg = $('Config').first().json;
if (!cfg.token || b.token !== cfg.token) throw new Error('Token inválido');
const p = b.pedido;
if (!p || !p.id || !p.cliente_telefone) return [];
const lista = (p.itens || []).map((i) =>
  `• ${i.qtd}× ${i.nome}${i.detalhe ? ' (' + i.detalhe + ')' : ''}${i.obs ? ' · obs: ' + i.obs : ''} — ${brl(i.preco)}`).join('\n');
const textos = {
  preparo: `Seu pedido *#${p.id}* foi confirmado e já está sendo preparado!`,
  pronto: `Seu pedido *#${p.id}* está pronto! Pode vir buscar no balcão.`,
  saiu: `Seu pedido *#${p.id}* saiu para entrega${p.entregador_nome ? ' com ' + p.entregador_nome : ''}! Já já chega aí.` +
    (p.pagamento === 'cartao' ? ' O entregador está levando a maquininha.' : p.pagamento === 'dinheiro' && p.troco_para ? ` Ele leva ${brl(p.troco_para - p.total)} de troco.` : ''),
  entregue: `Pedido *#${p.id}* entregue. Obrigado, ${p.cliente_nome}! Bom apetite e volte sempre à Naturalle Mania.`,
  cancelado: `Seu pedido *#${p.id}* foi cancelado. Qualquer dúvida, é só responder aqui.`,
};
if (!textos[p.status]) return [];
return [{ json: { numero: p.cliente_telefone, texto: textos[p.status] } }];

// só segue se o aviso chegou pela entrada 'evolution'
if ($input.first().json.rota !== 'evolution') return [];
const b = $input.first().json.body || {};
const cfg = $('Config').first().json;
const d = b.data || {};
const key = d.key || {};
const jid = key.remoteJid || '';
// só conversa individual, e nunca as mensagens que a própria loja mandou
if (b.event !== 'messages.upsert' || key.fromMe || !jid.endsWith('@s.whatsapp.net')) return [];
const m = d.message || {};
const tipo = d.messageType || Object.keys(m)[0] || '';
let texto = m.conversation || (m.extendedTextMessage && m.extendedTextMessage.text) || '';
let midia = null;
if (['imageMessage', 'audioMessage', 'documentMessage'].includes(tipo)) {
  const info = m[tipo] || {};
  texto = texto || info.caption || '';
  let base64 = m.base64 || d.base64 || '';
  let mime = info.mimetype || '';
  if (!base64) {
    // sem "Webhook Base64" ligado na Evolution: busca o arquivo nela
    try {
      const r = await this.helpers.httpRequest({ method: 'POST', json: true,
        url: `${cfg.evolution_url}/chat/getBase64FromMediaMessage/${cfg.evolution_instance}`,
        headers: { apikey: cfg.evolution_apikey }, body: { message: { key }, convertToMp4: false } });
      base64 = r.base64 || ''; mime = r.mimetype || mime;
    } catch (e) { /* segue sem o arquivo */ }
  }
  if (base64) midia = { tipo: tipo === 'audioMessage' ? 'audio' : 'imagem', mime, base64 };
}
if (!texto && !midia) return [];
return [{ json: { token: cfg.token, telefone: jid.split('@')[0], nome: d.pushName || '', texto, ...(midia || {}) } }];
